As a temporary workaround when using the SDK, e.g. to write plugins, you can do this (messing with "private" methods):

```js
  const password = process.env.OPENCODE_SERVER_PASSWORD
  if (password) {
    const username = process.env.OPENCODE_SERVER_USERNAME || "opencode"
    const authHeader = "Basic " + btoa(`${username}:${password}`)
    const innerClient = (client as any)._client
    if (innerClient?.interceptors?.request?.use) {
      innerClient.interceptors.request.use((req: Request) => {
        req.headers.set("Authorization", authHeader)
        return req
      })
    }
  }
```

